    {"name": "write", "arguments": {"path": "src/lib.rs", "overwrite": True, "content": "use std::collections::HashMap;\nuse std::sync::Arc;\n\npub type Value = i32;\npub type Result = std::result::Result<(), Error>;\n\npub struct Forth { stack: Vec<Value>, words: HashMap<String, Arc<Vec<Op>>> }\n\n#[derive(Debug, PartialEq, Eq)]\npub enum Error { DivisionByZero, StackUnderflow, UnknownWord, InvalidWord }\n\n#[derive(Clone)]\nenum Op { Push(Value), Add, Sub, Mul, Div, Dup, Drop, Swap, Over, Call(Arc<Vec<Op>>) }\n\nimpl Forth {\n    pub fn new() -> Forth { Self { stack: Vec::new(), words: HashMap::new() } }\n    pub fn stack(&self) -> &[Value] { &self.stack }\n\n    pub fn eval(&mut self, input: &str) -> Result {\n        let tokens: Vec<&str> = input.split_whitespace().collect();\n        let mut i = 0;\n        let mut ops = Vec::new();\n        while i < tokens.len() {\n            let token = tokens[i];\n            if token == \":\" {\n                if i + 2 >= tokens.len() { return Err(Error::InvalidWord); }\n                let name = tokens[i + 1].to_ascii_lowercase();\n                if is_number(&name) || builtin(&name).is_some() { return Err(Error::InvalidWord); }\n                i += 2;\n                let mut body = Vec::new();\n                while i < tokens.len() && tokens[i] != \";\" {\n                    body.push(self.compile(tokens[i])?);\n                    i += 1;\n                }\n                if i == tokens.len() { return Err(Error::InvalidWord); }\n                self.words.insert(name, Arc::new(body));\n            } else if token == \";\" {\n                return Err(Error::InvalidWord);\n            } else {\n                ops.push(self.compile(token)?);\n            }\n            i += 1;\n        }\n        self.execute(ops)\n    }\n\n    fn compile(&self, token: &str) -> std::result::Result<Op, Error> {\n        let word = token.to_ascii_lowercase();\n        if is_number(&word) { return word.parse::<Value>().map(Op::Push).map_err(|_| Error::UnknownWord); }\n        if let Some(op) = builtin(&word) { return Ok(op); }\n        self.words.get(&word).cloned().map(Op::Call).ok_or(Error::UnknownWord)\n    }\n\n    fn execute(&mut self, ops: Vec<Op>) -> Result {\n        let mut frames = vec![(ops, 0usize)];\n        while let Some((ops, index)) = frames.last_mut() {\n            if *index == ops.len() { frames.pop(); continue; }\n            let op = ops[*index].clone(); *index += 1;\n            match op {\n                Op::Push(n) => self.stack.push(n),\n                Op::Add | Op::Sub | Op::Mul | Op::Div => {\n                    if self.stack.len() < 2 { return Err(Error::StackUnderflow); }\n                    let b = *self.stack.last().unwrap(); let a = self.stack[self.stack.len() - 2];\n                    if matches!(op, Op::Div) && b == 0 { return Err(Error::DivisionByZero); }\n                    self.stack.truncate(self.stack.len() - 2);\n                    self.stack.push(match op { Op::Add => a.wrapping_add(b), Op::Sub => a.wrapping_sub(b), Op::Mul => a.wrapping_mul(b), Op::Div => a.checked_div(b).unwrap_or(a.wrapping_div(b)), _ => unreachable!() });\n                }\n                Op::Dup => { let a = *self.stack.last().ok_or(Error::StackUnderflow)?; self.stack.push(a); }\n                Op::Drop => { self.stack.pop().ok_or(Error::StackUnderflow)?; }\n                Op::Swap => { if self.stack.len() < 2 { return Err(Error::StackUnderflow); } let n = self.stack.len(); self.stack.swap(n - 1, n - 2); }\n                Op::Over => { if self.stack.len() < 2 { return Err(Error::StackUnderflow); } let n = self.stack.len(); self.stack.push(self.stack[n - 2]); }\n                Op::Call(body) => frames.push((body.as_ref().clone(), 0)),\n            }\n        }\n        Ok(())\n    }\n}\n\nfn is_number(s: &str) -> bool { !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit()) }\nfn builtin(s: &str) -> Option<Op> { Some(match s { \"+\" => Op::Add, \"-\" => Op::Sub, \"*\" => Op::Mul, \"/\" => Op::Div, \"dup\" => Op::Dup, \"drop\" => Op::Drop, \"swap\" => Op::Swap, \"over\" => Op::Over, _ => return None }) }\n\n#[cfg(test)]\nmod tests {\n    use super::{Error, Forth};\n    #[test]\n    fn arithmetic_stack_words_and_definitions() {\n        let mut f = Forth::new();\n        f.eval(\"1 2 + 3 * DUP OVER SWAP\").unwrap();\n        assert_eq!(f.stack(), &[9, 9, 9]);\n        f.eval(\": triple 3 * ; 4 triple\").unwrap();\n        assert_eq!(f.stack(), &[9, 9, 9, 12]);\n    }\n    #[test]\n    fn errors_and_case_insensitive_names() {\n        let mut f = Forth::new();\n        assert_eq!(f.eval(\"DROP\"), Err(Error::StackUnderflow));\n        assert_eq!(f.eval(\": Sq 2 * ; 3 SQ\"), Ok(()));\n        assert_eq!(f.stack(), &[6]);\n        assert_eq!(f.eval(\"1 0 /\"), Err(Error::DivisionByZero));\n        assert_eq!(f.eval(\": + 1 ;\"), Err(Error::InvalidWord));\n    }\n}\n"}},
